import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"SpaceX","description":"火箭与星空","frontmatter":{"title":"SpaceX","description":"火箭与星空","date":"2026-05-29T00:00:00.000Z","category":"置身事内","tags":["企业观察"],"order":4},"headers":[],"relativePath":"articles/zstn/firm/spacex.md","filePath":"articles/zstn/firm/spacex.md","articleMeta":{"updated":"2026-05-29","words":2555,"minutes":6}}`),a={name:`articles/zstn/firm/spacex.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="猛禽发动机" tabindex="-1">猛禽发动机 <a class="header-anchor" href="#猛禽发动机" aria-label="Permalink to “猛禽发动机”">​</a></h2><p><img src="/images/GUEhFjla8AANpDp.png" alt="GUEhFjla8AANpDp" width="3840" height="2414"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>如果不标注出来，是不是很容易认为最左侧是猛禽3？恰恰相反，从左到右依次是猛禽1、猛禽2和猛禽3。</p></div><h2 id="第十二次实验" tabindex="-1">第十二次实验 <a class="header-anchor" href="#第十二次实验" aria-label="Permalink to “第十二次实验”">​</a></h2><p><img src="/images/HI-A85lXgAA1txM.png" alt="HI-A85lXgAA1txM" width="3840" height="2090"></p><p><img src="/images/HI-A7kbXEAEZyU_-1779799793308-5.png" alt="HI-A7kbXEAEZyU_" width="3840" height="2160"></p><p><img src="/images/HJCQV_LWUAAL76d.png" alt="HJCQV_LWUAAL76d" width="3500" height="1974"></p><p><img src="/images/HJCQXuOWkAAF3rY.png" alt="HJCQXuOWkAAF3rY" width="3500" height="1941"></p><h2 id="ipo申报" tabindex="-1">IPO申报 <a class="header-anchor" href="#ipo申报" aria-label="Permalink to “IPO申报”">​</a></h2><h3 id="基本业务情况" tabindex="-1">基本业务情况 <a class="header-anchor" href="#基本业务情况" aria-label="Permalink to “基本业务情况”">​</a></h3><p>SpaceX 的使命：即让生命成为 <strong>多行星文明</strong> 、探究宇宙真谛，并将意识之光播撒至繁星之中。</p><p>SpaceX’s mission: to make life <strong>multiplanetary</strong> , to understand the true nature of the universe, and to extend the light of consciousness to the stars.</p><p>核心理念： <strong>工程至上文化（Engineering-First Culture）</strong> ，“第一性原理思考”。</p><p>SpaceX的三大业务：太空、星链链接、AI。星链连接业务2025年的EBITDA为72亿美元，是唯一盈利的业务。</p><table tabindex="0"><thead><tr><th style="text-align:left;">报告项目</th><th style="text-align:left;">2026 年 Q1 (截至3月31日)</th><th style="text-align:left;">2025 全年</th><th style="text-align:left;">同比/变动情况</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>合并总收入</strong></td><td style="text-align:left;">$46.94 亿</td><td style="text-align:left;">$186.74 亿</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>运营亏损</strong></td><td style="text-align:left;">$19.43 亿</td><td style="text-align:left;">$25.89 亿</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>调整后 EBITDA</strong></td><td style="text-align:left;">$11.27 亿</td><td style="text-align:left;">$65.84 亿</td><td style="text-align:left;">-</td></tr></tbody></table><p>各业务核心数据</p><table tabindex="0"><thead><tr><th style="text-align:left;">业务领域</th><th style="text-align:left;">报告维度</th><th style="text-align:left;">营收 (Revenue)</th><th style="text-align:left;">运营收益/亏损</th><th style="text-align:left;">调整后 EBITDA</th><th style="text-align:left;">研发投入 (Starship)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>太空 (Space)</strong></td><td style="text-align:left;">2026 Q1</td><td style="text-align:left;">$6.19 亿</td><td style="text-align:left;">-$6.62 亿 (亏损)</td><td style="text-align:left;">-$3.51 亿</td><td style="text-align:left;">$9.30 亿</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">2025 全年</td><td style="text-align:left;">$40.86 亿</td><td style="text-align:left;">-$6.57 亿 (亏损)</td><td style="text-align:left;">$6.53 亿</td><td style="text-align:left;">$30.04 亿</td></tr><tr><td style="text-align:left;"><strong>连接 (Connectivity)</strong></td><td style="text-align:left;">2026 Q1</td><td style="text-align:left;">$32.57 亿</td><td style="text-align:left;">+$11.88 亿 (收益)</td><td style="text-align:left;">$20.87 亿</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><em>(Starlink 驱动)</em></td><td style="text-align:left;">2025 全年</td><td style="text-align:left;">$113.87 亿</td><td style="text-align:left;">+$44.23 亿 (收益)</td><td style="text-align:left;">$71.68 亿</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>AI 业务</strong></td><td style="text-align:left;">2026 Q1</td><td style="text-align:left;">$8.18 亿</td><td style="text-align:left;">-$24.69 亿 (亏损)</td><td style="text-align:left;">-$6.09 亿</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><em>(新收购领域)</em></td><td style="text-align:left;">2025 全年</td><td style="text-align:left;">$32.01 亿</td><td style="text-align:left;">-$63.55 亿 (亏损)</td><td style="text-align:left;">-$12.37 亿</td><td style="text-align:left;">-</td></tr></tbody></table><p>资本支出对比：</p><table tabindex="0"><thead><tr><th style="text-align:left;">业务领域</th><th style="text-align:left;">2026 Q1 资本支出</th><th style="text-align:left;">2025 全年资本支出</th><th style="text-align:left;">备注</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>太空 (Space)</strong></td><td style="text-align:left;">$10.52 亿</td><td style="text-align:left;">$38.32 亿</td><td style="text-align:left;">用于基础设施及载具研发</td></tr><tr><td style="text-align:left;"><strong>连接 (Connectivity)</strong></td><td style="text-align:left;">$13.32 亿</td><td style="text-align:left;">$41.78 亿</td><td style="text-align:left;">主要支撑网络扩展</td></tr><tr><td style="text-align:left;"><strong>AI 业务</strong></td><td style="text-align:left;">$77.23 亿</td><td style="text-align:left;">$127.27 亿</td><td style="text-align:left;">反映高投入的早期发展阶段</td></tr><tr><td style="text-align:left;"><strong>总计</strong></td><td style="text-align:left;"><strong>$101.07 亿</strong></td><td style="text-align:left;"><strong>$207.37 亿</strong></td><td style="text-align:left;"></td></tr></tbody></table><p>三大业务是相辅相成的：</p><p>太空业务：通过可重复使用的 Falcon 9 和 Falcon Heavy 火箭，为商业、民用、国际及政府客户提供卫星、货物和载人任务的发射服务。除了向第三方销售发射任务外，还可以用于自身低成本发射数千颗近地轨道卫星、形成星链系统（Starlink ）。</p><p>星链：提供消费者宽带、企业解决方案、政府解决方案以及 Starlink Mobile。家庭消费者的峰值时段中位速度为 225 Mbps（大约 28MB/s，这个速度足以满足一般用户的需求）， 2026 年下半年利用 Starship 开始部署下一代 V3 卫星进一步扩容。<strong>Starlink Mobile：</strong> 提供“卫星到移动设备”的连接能力。星链的最核心作用是，全球覆盖，不需要基站，减少信号盲区。</p><p>AI则包括LLM大语言模型和芯片制造、数据中心等。打造<strong>真理探索前沿模型（Truth-Seeking Frontier Model）</strong> 。AI和太空业务又是怎么产生联系呢？ 那就是能源。太阳拥有整个太阳系约 99.8% 的能量，逻辑上最可行的前进方向， <strong>就是将高能耗的 AI 工作负载转移到轨道上</strong> ，因为那里的太阳能近乎恒定且永不中断。SpaceX 拥有独特的优势来部署和运营轨道数据中心，并最终在未来实现比地面数据中心更低的成本。</p><p>上述业务未来量化的潜在市场总量（TAM）为 <strong>28.5 万亿美元</strong>，特别地，全球市场预估数据中<strong>不包括</strong>中国和俄罗斯。</p><h3 id="股权结构" tabindex="-1">股权结构 <a class="header-anchor" href="#股权结构" aria-label="Permalink to “股权结构”">​</a></h3><p>SpaceX 采用了美股科技股常见的<strong>双层股权结构</strong>，将股票分为 <strong>A 类普通股（Class A）</strong> 和 <strong>B 类普通股（Class B）</strong>：<strong>A 类普通股：</strong> 本次公开发行的股票。通常每股对应 <strong>1 票</strong> 投票权。<strong>B 类普通股：</strong> 由马斯克及其他少数内部核心持有人持有。根据文件，B 类股拥有绝对的控制优势。更重要的是，SpaceX 的公司章程赋予了 B 类股一项特殊权力：<strong>只要有任何 B 类普通股在外流通，B 类股股东就有权直接选举董事会中的“多数席位”（即 Class B Directors）</strong>。</p><p>这个条款本质上建立了一道<strong>法律防火墙</strong>。它向所有准备买入 SpaceX 股票的股民宣告：<strong>“你们进来只能分享经济利益（分红或股价上涨），但公司的最高统治权（董事会），无论何时何地、无论股权怎么稀释，都将牢牢锁在 B 类股持有者（即马斯克）的手心里。”</strong></p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};